var memory=new SharedArrayBuffer(8);
$262.agent.start("
$262.agent.receiveBroadcast(function(buffer){
 const words=new BigInt64Array(buffer);
 const before=$262.agent.monotonicNow();
 const result=Atomics.wait(words,0,0n,2);
 const elapsed=$262.agent.monotonicNow()-before;
 $262.agent.report(elapsed);$262.agent.report(result);
 $262.agent.leaving();
});");
$262.agent.broadcast(memory);
var value;while((value=$262.agent.getReport())===null)$262.agent.sleep(1);
if(Number(value)<2)throw new Error("wait expired early");
